module polyline_solver(\n    input [31:0] a,\n    input [31:0] b,\n    output reg valid,\n    output reg [31:0] num,\n    output reg [31:0] den\n);\n\n    always @* begin\n        if (a >= b) begin\n            valid = 1'b1;\n            num   = a + b;\n            den   = (( (a - b) / (32'd2 * b) ) + 32'd1) * 32'd2;\n        end else begin\n            valid = 1'b0;\n            num   = 32'd0;\n            den   = 32'd0;\n        end\n    end\n\nendmodule